<template><Card class="s1-ui s1-compact-list"><header class="ui-header"><div><h2>商户申请审核</h2><p>核对当前提交版本。入驻、资料变更与资质续期在同一入口追溯。</p></div></header><DatasetSwitch :available="demoAvailable" :all="showTestData" @change="switchDataset"/><PageStatus v-bind="$data" :target="pendingTarget" @recover="recover()" @retry="recover(true)" @abandon="abandon"/><div class="ui-search"><label>商户／主体名称<Input v-model="q" maxlength="100" placeholder="搜索名称" @on-enter="search"/></label><label>申请类型<Select v-model="kind" clearable><Option v-for="v in kinds" :key="v" :value="v">{{status(v)}}</Option></Select></label><label>申请状态<Select v-model="statusFilter" clearable><Option v-for="v in states" :key="v" :value="v">{{status(v)}}</Option></Select></label><div class="ui-actions"><Button type="primary" @click="search">查询</Button><Button @click="reset">重置</Button></div></div><div class="ui-toolbar"><span>共 {{total}} 条申请</span><Button @click="reload">刷新当前页</Button></div><Table class="s1-list-table" v-compact-table :columns="columns" :data="records" :loading="loading" no-data-text="没有符合条件的申请"><template slot="name" slot-scope="{row}"><button class="ui-link ui-primary-name" @click="detail(row.id)">{{row.storeName||'店铺名称未提供'}}</button></template><template slot="kind" slot-scope="{row}">{{status(row.kind)}}</template><template slot="state" slot-scope="{row}"><StatusTag :value="row.status"/></template><template slot="time" slot-scope="{row}">{{date(row.submittedAt)}}</template><template slot="version" slot-scope="{row}">提交 v{{row.revision}} · <span class="ui-meta">数据 v{{row.version}}</span></template><template slot="operations" slot-scope="{row}"><Button size="small" @click="detail(row.id)">查看申请</Button></template></Table><Page class="ui-pagination" :total="total" :current="page" :page-size="size" show-total @on-change="changePage"/></Card></template>
<script>import page from './page';import PageStatus from './components/PageStatus';import StatusTag from './components/StatusTag';const keys=['q','kind','statusFilter'];export default {mixins:[page],components:{PageStatus,StatusTag},data:()=>({q:'',kind:'',statusFilter:'SUBMITTED',kinds:['ADMISSION','PROFILE_CHANGE','QUALIFICATION_CHANGE'],states:['DRAFT','SUBMITTED','APPROVED','REJECTED'],columns:[{title:'店铺名称',slot:'name',minWidth:190},{title:'主体名称',key:'legalName',minWidth:210,tooltip:true},{title:'申请类型',slot:'kind',minWidth:140},{title:'状态',slot:'state',width:110},{title:'提交时间（上海）',slot:'time',minWidth:185},{title:'版本',slot:'version',width:115},{title:'操作',slot:'operations',width:120}]}),mounted(){this.initializeList(keys,{statusFilter:'SUBMITTED'});this.reload();},methods:{reload(){return this.load('/applications',{kind:this.kind||undefined,status:this.statusFilter||undefined,q:this.q||undefined},true);},search(){this.page=1;this.remember(keys);this.reload();},reset(){this.q='';this.kind='';this.statusFilter='';this.search();},changePage(v){this.page=v;this.remember(keys);this.reload();}}};</script>
